const content = $json.choices[0].message.content;
const strategy = JSON.parse(content);

const original = $("Normalize Topic Input").item.json;

// Remove source metadata generated by the AI
delete strategy.source;
delete strategy.source_row;

// Editorial inputs are decided upstream
const contentObjective = original["Content objective"] || "";

const primaryKeyword =
  original["Primary Keyword"] ||
  original.keyword ||
  "";

const topic = original.Topic || "";

return {
  json: {
    // Preserve original Google Sheets metadata
    Topic: topic,
    source_row: original.idea_source === 'memory' ? 'ACF Blogs Ideas|' + original.memory_context_id + '|' + primaryKeyword.toLowerCase().trim().replace(/\s+/g, '-') : original.row_number,

    // Include all generated strategy fields
    ...strategy,

    // Upstream editorial inputs always take precedence
    content_objective: contentObjective,
    primary_keyword: primaryKeyword,
    idea_source: original.idea_source || 'sheet'
  }
};

