const response = $json.result;
if (!response || response.isError || $json.error) throw new Error('Cannot list ACF Blogs Ideas: ' + JSON.stringify($json.error || response));
const text = response.structuredContent?.result || response.content?.find(c => c.type === 'text')?.text;
if (typeof text !== 'string') throw new Error('ACF Blogs Ideas list has no readable result');
const parts = Object.fromEntries(new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit'
}).formatToParts(new Date()).filter(p => p.type !== 'literal').map(p => [p.type, Number(p.value)]));
const today = new Date(Date.UTC(parts.year, parts.month - 1, parts.day));
const monday = new Date(today.getTime() - ((today.getUTCDay() + 6) % 7) * 86400000);
const friday = new Date(monday.getTime() + 4 * 86400000);
const ordinal = n => n + (n % 100 >= 11 && n % 100 <= 13 ? 'th' : ({1:'st',2:'nd',3:'rd'}[n % 10] || 'th'));
const month = d => new Intl.DateTimeFormat('en-GB', {month:'short',timeZone:'UTC'}).format(d);
const startYear = monday.getUTCFullYear();
const weekTitle = ordinal(monday.getUTCDate()) + ' ' + month(monday) +
  (startYear === friday.getUTCFullYear() ? '' : ' ' + startYear) + '-' +
  ordinal(friday.getUTCDate()) + ' ' + month(friday) + ' ' + friday.getUTCFullYear();
const norm = s => s.normalize('NFKC').replace(/[–—]/g, '-').replace(/\s*-\s*/g, '-').replace(/\s+/g,' ').trim().toLowerCase();
const matches = [...text.matchAll(/^- \*\*(.+?)\*\* \(contextId: ([0-9a-f-]{36})\)/gmi)]
  .filter(m => norm(m[1]) === norm(weekTitle));
if (matches.length > 1) throw new Error('Duplicate weekly memories named ' + weekTitle);
if (!matches.length && !/No items found|Found \d+ item\(s\)/i.test(text)) throw new Error('Unrecognized ACF item-list format');
return {json:{memory_week:weekTitle,memory_context_id:matches[0]?.[2] || '',memory_bucket_id:'REPLACE_WITH_YOUR_ACF_BLOG_IDEAS_BUCKET_ID'}};

