const text = response.structuredContent?.result || response.content?.find(c => c.type === 'text')?.text;
if (typeof text !== 'string') throw new Error('Weekly ideas has no readable result');
const marker = text.match(/\nupdatedAt: [^\n]+\n\n/);
if (!marker) throw new Error('Unrecognized weekly ideas content format');
const content = text.slice(marker.index + marker[0].length).trim();
if (!content) throw new Error('Weekly ideas memory is empty');
if (content.length > 20000) throw new Error('Weekly ideas memory exceeds 20,000 characters');
const source = $('Select Current Week Memory').item.json;
return {json:{...source,memory_content:content}};

const note = $json;
const system = `You organize a marketing team's weekly ideas for AI Context Flow.
Extract only distinct BLOG article ideas from the note. Social-only ideas are excluded.
An inspiration or point of view is a hypothesis, not a verified fact.
Return JSON only: {"blog_ideas":[{"topic":"","primary_keyword":"","angle":"","pov":"","product_relevance":"","content_objective":"authority or product_education","strategic_pillar":""}]}.
Return at most 3 ideas. If the note contains no usable blog idea, return an empty array.
Keep the team's meaning. Do not invent search volume, keyword difficulty, evidence, URLs, product capabilities, or approval.
The keyword is a tentative search phrase for the existing research workflow; its intent and suitability will be researched there.`;
return {json:{...note,system_prompt:system,user_prompt:'Weekly memory: '+note.memory_week+'\n\n'+note.memory_content}};

