const raw = $input.first().json.choices?.[0]?.message?.content;
if (!raw) throw new Error('No blog idea extraction response');
let data;
try {data = JSON.parse(raw.replace(/^```json\s*/i,'').replace(/^```\s*/,'').replace(/```\s*$/,'').trim());}
catch(e) {throw new Error('Blog idea extraction was not JSON: '+e.message);}
if (!Array.isArray(data.blog_ideas) || data.blog_ideas.length > 3) throw new Error('Expected 0-3 blog ideas');
const source = $('Prepare Memory Idea Candidates').first().json;
const seen = new Set();
return data.blog_ideas.map((v,i) => {
  if (!v || typeof v !== 'object') throw new Error('Invalid blog idea at index '+i);
  const topic = String(v.topic || '').trim();
  const keyword = String(v.primary_keyword || '').trim();
  if (!topic || !keyword) throw new Error('Blog idea needs a topic and tentative keyword');
  const key = keyword.toLowerCase();
  if (seen.has(key)) throw new Error('Duplicate keyword in weekly ideas: '+keyword);
  seen.add(key);
  const objective = String(v.content_objective || 'authority').trim().toLowerCase();
  if (!['authority','product_education'].includes(objective)) throw new Error('Invalid content objective for '+topic);
  return {json:{
    Topic:topic,'Primary Keyword':keyword,'Strategic Pillar':String(v.strategic_pillar||'').trim(),
    'Product relevance':String(v.product_relevance||'').trim(),Angle:String(v.angle||'').trim(),
    POV:String(v.pov||'').trim(),'Content objective':objective,
    'Search Volume':'',KD:'',Intent:'',Status:'idea',Generate:true,
    idea_source:'memory',memory_week:source.memory_week,
    memory_context_id:source.memory_context_id,memory_idea_index:i+1,
    row_number:null
  },pairedItem:{item:0}};
});
